};

/**
 * @method
 * @name setCorpInfo
 * @description set Corp Info 처리
 * @param {String} isurCd isurCd
 * @param {*} corpRegNo corpRegNo
 * @param {*} bzRegNo bzRegNo
 * @param {String} repIsuCd repIsuCd
 * @param {String} repIsuSrtCd repIsuSrtCd
 * @param {String} comNm comNm
 * @param {String} comEngNm comEngNm
 * @param {String} ceoNm ceoNm
 * @param {String} zipCd zipCd
 * @param {*} addr addr
 * @param {*} hPage hPage
 * @param {String} cntrIsoCd cntrIsoCd
 * @param {String} foundDd foundDd
 * @param {*} corpTelNo corpTelNo
 * @returns {void}
 * @hidden N
 */
scwin.setCorpInfo = function (isurCd, corpRegNo, bzRegNo, repIsuCd, repIsuSrtCd, comNm, comEngNm, ceoNm, zipCd, addr, hPage, cntrIsoCd, foundDd, corpTelNo) {
    const objName = 'null';
    if (objName === 'null' || objName === 'undefined' || objName === '') {
        scwin.setCorpInfoOrg(isurCd, corpRegNo, bzRegNo, repIsuCd, repIsuSrtCd, comNm, comEngNm, ceoNm, zipCd, addr, hPage, cntrIsoCd, foundDd, corpTelNo);
    } else {
        (((scwin.openerScwin()) !== scwin && typeof (scwin.openerScwin()).setComInfo === 'function' ? (scwin.openerScwin()).setComInfo(objName, isurCd, repIsuCd) : void 0), $c.win.closePopup([objName, isurCd, repIsuCd]));
        $c.win.closePopup();
    }
};

/**
 * @method
 * @name setCorpInfoOrg
 * @description set Corp Info Org 처리
 * @param {String} isurCd isurCd
 * @param {*} corpRegNo corpRegNo
 * @param {*} bzRegNo bzRegNo
 * @param {String} repIsuCd repIsuCd
 * @param {String} repIsuSrtCd repIsuSrtCd
 * @param {String} comNm comNm
 * @param {String} comEngNm comEngNm
 * @param {String} ceoNm ceoNm
 * @param {String} zipCd zipCd
 * @param {*} addr addr
 * @param {*} hPage hPage
 * @param {String} cntrIsoCd cntrIsoCd
 * @param {String} foundDd foundDd
 * @param {*} corpTelNo corpTelNo
 * @returns {void}
 * @hidden N
 */
scwin.setCorpInfoOrg = function (isurCd, corpRegNo, bzRegNo, repIsuCd, repIsuSrtCd, comNm, comEngNm, ceoNm, zipCd, addr, hPage, cntrIsoCd, foundDd, corpTelNo) {
    let str = "";
    str += "isurCd : " + isurCd + "\n";
    str += "corpRegNo : " + corpRegNo + "\n";
    str += "repIsuSrtCd : " + repIsuSrtCd + "\n";
    str += "comNm : " + comNm + "\n";
    str += "bzRegNo : " + bzRegNo + "\n";
    str += "comEngNm : " + comEngNm + "\n";
    str += "ceoNm : " + ceoNm + "\n";
    const returnKey = '' + dma_pageContext.get("returnKey") + '';
    try {
        (((scwin.openerScwin()) !== scwin && typeof (scwin.openerScwin()).setCorpInfo === 'function' ? (scwin.openerScwin()).setCorpInfo(isurCd, corpRegNo, bzRegNo, repIsuCd, repIsuSrtCd, comNm, comEngNm, ceoNm, zipCd, addr, hPage, cntrIsoCd, foundDd, corpTelNo) : void 0), $c.win.closePopup([isurCd, corpRegNo, bzRegNo, repIsuCd, repIsuSrtCd, comNm, comEngNm, ceoNm, zipCd, addr, hPage, cntrIsoCd, foundDd, corpTelNo]));
        $c.win.closePopup();
    } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'jldfil59000' }); return; }
};

/**
 * @method
 * @name opener
 * @description 부모 화면 scope(browserPopup/pageFramePopup 공통 — $c.win.getOpenerScope). 단독 진입이거나 부모가 닫혀 없으면
 * @returns {Object} 부모 화면 scope 또는 빈 scope
 * @hidden N
 */
scwin.opener = function () {
    const scope = ($c.win && $c.win.getOpenerScope) ? $c.win.getOpenerScope() : null;
    return scope || { getComponentById: function () { return null; }, scwin: {} };
};

/**
 * @method
 * @name openerScwin
 * @description 부모 화면의 scwin(함수·전역 접근용). 부모가 없으면 빈 객체
 * @returns {Object} 부모 scwin 또는 {}
 * @hidden N
 */
scwin.openerScwin = function () {
    return scwin.opener().scwin || {};
};
